$encrypted = encrypt($plaintext, $key);
$decrypted = decrypt($encrypted, $key);

if ($decrypted !== $plaintext) {
    $failures[] = "Test 1 Failed: Basic roundtrip. Expected '{$plaintext}', got '" . var_export($decrypted, true) . "'";
