    $failures[] = "Test 2 Failed: Different encryptions should produce different ciphertext due to random IV.";
}

// Test 3: Wrong key fails decryption
$encrypted = encrypt("secret data", "correct-key");
$result = decrypt($encrypted, "wrong-key");

if ($result === "secret data") {
    $failures[] = "Test 3 Failed: Decryption with wrong key should not return original text.";
}

// Output results
if (empty($failures)) {
    echo "ALL TESTS PASSED" . PHP_EOL;
    exit(0);
} else {
    foreach ($failures as $failure) {
        echo $failure . PHP_EOL;
    }
    exit(1);
}
EOF
