def factorial_naive(n):
    """Naive recursive factorial (NOT tail-recursive)."""
    if n == 0:
        return 1
    return n * factorial_naive(n - 1)


def factorial_tail_recursive(n, accumulator=1):
    """Tail-recursive factorial using an accumulator."""
    if n == 0:
        return accumulator
    return factorial_tail_recursive(n - 1, n * accumulator)


def factorial_eliminated(n):
    """Iterative version simulating tail-recursion elimination."""
    accumulator = 1
    while n > 0:
        accumulator *= n
        n -= 1
    return accumulator


def sum_list_naive(lst):
    """Naive recursive list sum (NOT tail-recursive)."""
    if not lst:
        return 0
    return lst[0] + sum_list_naive(lst[1:])


def sum_list_tail_recursive(lst, accumulator=0):
    """Tail-recursive list sum using an accumulator."""
    if not lst:
        return accumulator
    return sum_list_tail_recursive(lst[1:], accumulator + lst[0])


def sum_list_eliminated(lst):
    """Iterative version simulating tail-recursion elimination."""
    accumulator = 0
    for item in lst:
        accumulator += item
    return accumulator
EOF
