package filecache

import (
	"fmt"
	"path/filepath"
	"strings"
	"time"

	"github.com/gohugoio/hugo/config"
	"github.com/gohugoio/hugo/helpers"
	"github.com/spf13/afero"
	"github.com/spf13/cast"
)

// CacheKey represents a cache key.
type CacheKey string

// FileCacheConfig represents a configuration for a single file cache.
type FileCacheConfig struct {
	// The path to the cache directory.
	Path string

	// Max age in seconds. 0 means no cache, -1 means forever.
	MaxAge int
}

// FileCache represents a named file cache.
type FileCache struct {
	Fs afero.Fs

	config FileCacheConfig
}

// Item represents a cache item.
type Item struct {
	// The content of the cache item.
	Content []byte
}

// GetOrCreate gets the content for the given key from the cache if it exists
// and is not expired, otherwise it calls the create function and caches the
// result.
func (c *FileCache) GetOrCreate(key string, create func() ([]byte, error)) ([]byte, error) {
	item, err := c.Get(key)
	if err != nil {
		return nil, err
	}
	if item != nil {
		return item.Content, nil
	}

	content, err := create()
	if err != nil {
		return nil, err
	}

	err = c.Set(key, content)
	if err != nil {
		return nil, err
	}

	return content, nil
}

// Get returns the content for the given key if it exists and is not expired.
// Returns nil if the key is not found or expired.
func (c *FileCache) Get(key string) (*Item, error) {
	if c.config.MaxAge == 0 {
		return nil, nil
	}

	filename := c.filename(key)
	exists, err := helpers.Exists(filename, c.Fs)
	if err != nil {
		return nil, err
	}
	if !exists {
		return nil, nil
	}

	if c.config.MaxAge > 0 {
		fi, err := c.Fs.Stat(filename)
		if err != nil {
			return nil, err
		}
		if time.Since(fi.ModTime()) > time.Duration(c.config.MaxAge)*time.Second {
			// Expired
			return nil, nil
		}
	}

	content, err := afero.ReadFile(c.Fs, filename)
	if err != nil {
		return nil, err
	}

	return &Item{Content: content}, nil
}

// Set writes the content for the given key to the cache.
func (c *FileCache) Set(key string, content []byte) error {
	if c.config.MaxAge == 0 {
		return nil
	}

	filename := c.filename(key)
	return helpers.WriteToDisk(filename, bytes.NewReader(content), c.Fs)
}

// Delete removes the given key from the cache.
func (c *FileCache) Delete(key string) error {
	filename := c.filename(key)
	return c.Fs.Remove(filename)
}

func (c *FileCache) filename(key string) string {
	return filepath.Join(c.config.Path, key)
}

// FileCaches represents a set of named file caches.
type FileCaches struct {
	caches map[CacheKey]*FileCache
}

// Get returns the file cache for the given key.
func (c *FileCaches) Get(key CacheKey) *FileCache {
	return c.caches[key]
}

// NewFileCaches creates a new set of file caches from the given configuration.
func NewFileCaches(cfg config.Provider, fs afero.Fs) (*FileCaches, error) {
	caches := make(map[CacheKey]*FileCache)

	cacheConfigs := defaultCacheConfigs()

	// Override with user configuration
	if cfg.IsSet("caches") {
		userCaches := cfg.GetStringMap("caches")
		for name, userConfig := range userCaches {
			if m, ok := userConfig.(map[string]interface{}); ok {
				if c, ok := cacheConfigs[CacheKey(name)]; ok {
					if path, ok := m["path"]; ok {
						c.Path = cast.ToString(path)
					}
					if maxAge, ok := m["maxAge"]; ok {
						c.MaxAge = cast.ToInt(maxAge)
					}
				} else {
					// New cache defined by user
					cacheConfigs[CacheKey(name)] = FileCacheConfig{
						Path:   cast.ToString(m["path"]),
						MaxAge: cast.ToInt(m["maxAge"]),
					}
				}
			}
		}
	}

	// Resolve paths
	for name, cc := range cacheConfigs {
		path, err := resolvePath(cfg, cc.Path)
		if err != nil {
			return nil, fmt.Errorf("failed to resolve cache path for %q: %s", name, err)
		}
		caches[name] = &FileCache{
			Fs:     afero.NewBasePathFs(fs, path),
			config: FileCacheConfig{Path: path, MaxAge: cc.MaxAge},
		}
	}

	return &FileCaches{caches: caches}, nil
}

func resolvePath(cfg config.Provider, path string) (string, error) {
	// Replace placeholders
	path = strings.Replace(path, ":resourceDir", cfg.GetString("resourceDir"), 1)
	path = strings.Replace(path, ":cacheDir", cfg.GetString("cacheDir"), 1)
	path = strings.Replace(path, ":project", cfg.GetString("workingDir"), 1)

	return filepath.FromSlash(path), nil
}

func defaultCacheConfigs() map[CacheKey]FileCacheConfig {
	return map[CacheKey]FileCacheConfig{
		CacheKey("image"): {
			Path:   ":resourceDir/_gen/images",
			MaxAge: -1,
		},
		CacheKey("assets"): {
			Path:   ":resourceDir/_gen/assets",
			MaxAge: -1,
		},
		CacheKey("getJSON"): {
			Path:   ":cacheDir/getjson",
			MaxAge: 600,
		},
		CacheKey("getCSV"): {
			Path:   ":cacheDir/getcsv",
			MaxAge: 600,
		},
		CacheKey("pygments"): {
			Path:   ":cacheDir/pygments",
			MaxAge: -1,
		},
	}
}
