// CacheKey represents a cache key.
type CacheKey string

// FileCacheConfig represents a configuration for a single file cache.
type FileCacheConfig struct {
	// The path to the cache directory.
	Path string

	// Max age in seconds. 0 means no cache, -1 means forever.
	MaxAge int
}

// FileCache represents a named file cache.
type FileCache struct {
	Fs afero.Fs

	config FileCacheConfig
}

// Item represents a cache item.
type Item struct {
	// The content of the cache item.
	Content []byte
}

// GetOrCreate gets the content for the given key from the cache if it exists
// and is not expired, otherwise it calls the create function and caches the
// result.
func (c *FileCache) GetOrCreate(key string, create func() ([]byte, error)) ([]byte, error) {
	item, err := c.Get(key)
	if err != nil {
		return nil, err
	}
	if item != nil {
		return item.Content, nil
	}

	content, err := create()
	if err != nil {
		return nil, err
	}

	err = c.Set(key, content)
	if err != nil {
		return nil, err
	}

	return content, nil
}

// Get returns the content for the given key if it exists and is not expired.
// Returns nil if the key is not found or expired.
func (c *FileCache) Get(key string) (*Item, error) {
	if c.config.MaxAge == 0 {
		return nil, nil
	}

	filename := c.filename(key)
	exists, err := helpers.Exists(filename, c.Fs)
	if err != nil {
		return nil, err
	}
	if !exists {
		return nil, nil
	}

	if c.config.MaxAge > 0 {
		fi, err := c.Fs.Stat(filename)
		if err != nil {
			return nil, err
		}
		if time.Since(fi.ModTime()) > time.Duration(c.config.MaxAge)*time.Second {
			// Expired
			return nil, nil
		}
	}

	content, err := afero.ReadFile(c.Fs, filename)
	if err != nil {
		return nil, err
	}

	return &Item{Content: content}, nil
}

// Set writes the content for the given key to the cache.
func (c *FileCache) Set(key string, content []byte) error {
	if c.config.MaxAge == 0 {
		return nil
	}

	filename := c.filename(key)
	return helpers.WriteToDisk(filename, bytes.NewReader(content), c.Fs)
}

// Delete removes the given key from the cache.
func (c *FileCache) Delete(key string) error {
	filename := c.filename(key)
	return c.Fs.Remove(filename)
}

func (c *FileCache) filename(key string) string {
	return filepath.Join(c.config.Path, key)
}

