type FileCaches struct {
	caches map[CacheKey]*FileCache
}

// Get returns the file cache for the given key.
func (c *FileCaches) Get(key CacheKey) *FileCache {
	return c.caches[key]
}

// NewFileCaches creates a new set of file caches from the given configuration.
func NewFileCaches(cfg config.Provider, fs afero.Fs) (*FileCaches, error) {
	caches := make(map[CacheKey]*FileCache)

	cacheConfigs := defaultCacheConfigs()

	// Override with user configuration
	if cfg.IsSet("caches") {
		userCaches := cfg.GetStringMap("caches")
		for name, userConfig := range userCaches {
			if m, ok := userConfig.(map[string]interface{}); ok {
				if c, ok := cacheConfigs[CacheKey(name)]; ok {
					if path, ok := m["path"].(string); ok {
						c.Path = path
					}
					if maxAge, ok := m["maxAge"]; ok {
						c.MaxAge = cast.ToInt(maxAge)
					}
				} else {
					// New cache defined by user
					cacheConfigs[CacheKey(name)] = FileCacheConfig{
						Path:   cast.ToString(m["path"]),
						MaxAge: cast.ToInt(m["maxAge"]),
					}
				}
			}
		}
	}

	// Resolve paths
	for name, cc := range cacheConfigs {
		path, err := resolvePath(cfg, cc.Path)
		if err != nil {
			return nil, fmt.Errorf("failed to resolve cache path for %q: %s", name, err)
		}
		caches[name] = &FileCache{
			Fs:     afero.NewBasePathFs(fs, path),
			config: FileCacheConfig{Path: path, MaxAge: cc.MaxAge},
		}
	}

	return &FileCaches{caches: caches}, nil
}

