	// Replace placeholders
	path = strings.Replace(path, ":resourceDir", cfg.GetString("resourceDir"), 1)
	path = strings.Replace(path, ":cacheDir", cfg.GetString("cacheDir"), 1)
	path = strings.Replace(path, ":project", cfg.GetString("workingDir"), 1)

	return filepath.FromSlash(path), nil
}

